CREATE TABLE public_spaces(workspace_id TEXT PRIMARY KEY REFERENCES workspaces(id) ON DELETE CASCADE,enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN(0,1)),revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE public_lists(list_id TEXT PRIMARY KEY REFERENCES lists(id) ON DELETE CASCADE,enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN(0,1)),revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE public_access_events(id INTEGER PRIMARY KEY,kind TEXT NOT NULL,entity_id TEXT NOT NULL,actor_id TEXT NOT NULL REFERENCES users(id),enabled INTEGER NOT NULL,occurred_at INTEGER NOT NULL DEFAULT(unixepoch()));
